{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A polar nucleoside-like compound measured in humans has an absolute oral bioavailability of only 4% (range 1-9%), far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Gemcitabine, a polar nucleoside analog, has human oral bioavailability of only about 10%, with low systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Levovirin, a highly polar nucleoside, has approximately 10% human oral bioavailability due to very low permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The ribonucleoside analog R1479 has an estimated human absolute oral bioavailability of 6-18%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phlorizin, a polar glycoside, has poor/low oral bioavailability in humans, limiting its clinical use.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, fully ionized, highly polar macrocycle (MW ~1272 Da, TPSA ~460 Å², logD -3.35). Multiple high-transfer experimental analogues—polar nucleosides and glycosides—show human oral bioavailability well below 20% (4-18%, often ~10%). The physicochemical prior and experimental evidence align, and no affirmative evidence supports F≥20%. Therefore predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability data for a corrinoid/B12-like macrocycle of this exact size; evidence comes from smaller polar nucleosides and glycosides.",
    "No data on possible active uptake mechanisms (e.g., transporter-mediated or intrinsic-factor-like absorption) for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

